// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        uint256 before = c.tokenBalance(caller);
        vm.assume(before == 0);

        Helper h = new Helper();

        uint256 helperBefore = c.tokenBalance(address(h));
        vm.assume(helperBefore == 0);

        h.callAirDrop(c);

        assertTrue(c.tokenBalance(address(h)) == 20);
    }
}

contract Helper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function callAirDrop(ModifierEntrancy target) external {
        target.airDrop();
    }
}
